/**
 * Parametric route model (Phase 2). Types only.
 *
 * Generated by products/routing/route-generator.mjs from the lab's pipeline outputs
 * (geometry() + qtyFor()), NOT parsed from the 3D scene. Every run references a P1 product
 * row by `productId` and a qtyFor() driver for its length/weight target.
 *
 * Units: coordinates and extents in feet; `lengthCu` in centi-feet (integer, so sums are
 * exact); section sizes in inches.
 *
 * CLASH-READY FIELDS (P3 will use them; no clash rules exist here):
 *   - Segment.extents      axis-aligned bounding box of the centerline plus half cross-section
 *                          plus insulation (g.insulThk). Hanger/clearance envelopes are NOT included.
 *   - Segment.clearanceClass  SHAFT | PLENUM_STANDARD | ACCESS_SERVICE (classification only)
 *   - Segment.clashClass   copied from the P1 product row (ClashClass in mep-product.ts)
 *   - Fitting.hostSegmentId + stationCu   where a fitting sits on a segment
 */
import type { ClashClass } from "../schema/mep-product";

export type ClearanceClass = "SHAFT" | "PLENUM_STANDARD" | "ACCESS_SERVICE";
export type SegmentKind = "riser" | "trunk" | "branch";
export type RouteFittingType = "tee" | "tee_reducing" | "elbow_90" | "transition";
export type Point = { x: number; y: number; z: number };
export type Extents = { min: Point; max: Point; includesInsulationIn: number };

export interface RouteSegment {
  id: string;
  runId: string;
  productId: string;
  kind: SegmentKind;
  floor: number;
  zone: number;
  riserIndex?: number;
  a: Point;
  b: Point;
  lengthCu: number;
  lengthFt: number;
  section: { widthIn: number; heightIn: number; nps?: number; gauge?: string };
  weightRateLbPerFt: number;
  extents: Extents;
  clearanceClass: ClearanceClass;
  clashClass: ClashClass;
}

export interface RouteFitting {
  id: string;
  type: RouteFittingType;
  hostSegmentId: string;
  stationCu: number;
  joins: string | null;
}

export interface RouteRun {
  id: string;
  productId: string;
  ductType: string | null;
  pipeType: string | null;
  activityId: string;
  driver: string;
  driverUnit: "LB" | "LF";
  target: { unit: "LB" | "LF"; value: number; driverTotal: number; source: string };
  /** duct runs only: LF derived from DUCT_LBS; not a pipeline output. */
  derivedLf: { value: number; status: "derived-not-in-estimate"; proposedDriver: "DUCT_LF" } | null;
  expectedWeightLb: number;
  weightBasis: string;
  calibration: {
    branchesPerZone: number;
    horizontalScale: number;
    nominalZoneLenFt: number;
    footprintFt: { x: number; y: number };
    maxFootprintOverrunFt: number;
  };
  segments: RouteSegment[];
  fittings: RouteFitting[];
}

export interface RouteModel {
  label: string;
  dataMode: string;
  layout: { floors: number; zones: number; risers: number; floorToFloorFt: number; plenumFt: number; insulationIn: number; footprintFt: { x: number; y: number } };
  runs: RouteRun[];
  exclusions: { productId: string; reason: string }[];
}
